int nearest(const set<int>& s, int x) {
    auto it = s.lower_bound(x);
    if (it == s.begin()) return *it;
    if (it == s.end()) return *prev(it);
    int hi = *it;
    int lo = *prev(it);
    return 1LL * x - lo < 1LL * hi - x ? lo : hi;
}

